/**
 * GENRE MARKS — the filter's icon set, keyed by TMDB genre id.
 *
 * ▸ EVERY PATH HERE WAS EXTRACTED FROM THE PAPER BOARDS with `get_jsx`, never
 *   read off a screenshot. If a mark needs changing, it changes on the board
 *   first and is re-extracted — this file is a transcription, not a source.
 *
 * ▸ TWO WEIGHTS, ON PURPOSE. Bryan drew most of these as FILLED single-path
 *   glyphs; four he deliberately kept as the original hairline drawings
 *   ("I couldn't think of an icon better than those two… for thriller it's
 *   like your heart pulsing", and action/romance "are just simple"). So a mark
 *   carries its own render mode rather than the set assuming one.
 *
 * ▸ EIGHTEEN, NOT NINETEEN. TMDB returns nineteen movie genres; TV MOVIE
 *   (10770) is deliberately absent, because FORMAT already cycles film/shows
 *   and two controls asking one question is exactly how a filter ends up
 *   disagreeing with itself. Its mark exists on the board and is not used.
 *
 * ▸ VIEWBOXES VARY WILDLY (14², 56², 98², 2048²) because the marks came from
 *   different sources. That is fine and must not be "normalised" — each mark
 *   carries its own box and the renderer scales it to the cell.
 */

export type GenrePath = {
  d: string;
  /** Filled glyphs carry no stroke; hairline marks carry no fill. */
  filled?: boolean;
  strokeWidth?: number;
  round?: boolean;
};

export type GenreMark = {
  viewBox: string;
  paths: GenrePath[];
};

/** The eighteen the filter offers, in TMDB's own order. */
